{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-9an7zs/src/lexer.js","content":"/**
 * The scanner for the small language described by the task. `scan(input)`
 * walks a UTF-8 source string and returns every token it holds, in order,
 * or throws a `LexError` carrying the line, column and reason of the first
 * problem it hits.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

const LETTER_RE = /\p{L}/u
const IDENT_START_RE = /[\p{L}_]/u
const IDENT_PART_RE = /[\p{L}0-9_]/u

export class LexError extends Error {
  constructor(line, column, reason) {
    super(reason)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

function isDecDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return c !== undefined && ((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
}

function isBinDigit(c) {
  return c === '0' || c === '1'
}

function isOctDigit(c) {
  return c !== undefined && c >= '0' && c <= '7'
}

export function scan(input) {
  const chars = Array.from(input)
  let pos = 0
  let line = 1
  let col = 1

  function peek(offset = 0) {
    return chars[pos + offset]
  }

  function here() {
    return { line, column: col }
  }

  function advance() {
    const c = chars[pos]
    pos++
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else {
      col++
    }
    return c
  }

  function fail(p, reason) {
    throw new LexError(p.line, p.column, reason)
  }

  function readRun(isDigit) {
    let text = advance() // first digit, already validated by the caller
    for (;;) {
      if (peek() === '_' && isDigit(peek(1))) {
        text += advance()
        text += advance()
      } else if (isDigit(peek())) {
        text += advance()
      } else {
        break
      }
    }
    return text
  }

  function scanNumber(start) {
    let text = ''
    let zeroDigitPrefix = false

    const c0 = peek()
    const c1 = peek(1)
    if (c0 === '0' && (c1 === 'x' || c1 === 'X')) {
      text += advance() + advance()
      if (isHexDigit(peek())) text += readRun(isHexDigit)
      else zeroDigitPrefix = true
    } else if (c0 === '0' && (c1 === 'b' || c1 === 'B')) {
      text += advance() + advance()
      if (isBinDigit(peek())) text += readRun(isBinDigit)
      else zeroDigitPrefix = true
    } else if (c0 === '0' && (c1 === 'o' || c1 === 'O')) {
      text += advance() + advance()
      if (isOctDigit(peek())) text += readRun(isOctDigit)
      else zeroDigitPrefix = true
    } else {
      text += readRun(isDecDigit)
      if (peek() === '.' && isDecDigit(peek(1))) {
        text += advance()
        text += readRun(isDecDigit)
      }
      if (peek() === 'e' || peek() === 'E') {
        const hasSign = peek(1) === '+' || peek(1) === '-'
        const digitAfter = hasSign ? peek(2) : peek(1)
        if (isDecDigit(digitAfter)) {
          text += advance()
          if (hasSign) text += advance()
          text += readRun(isDecDigit)
        }
      }
    }

    let hadError = zeroDigitPrefix
    const t = peek()
    if (t !== undefined && (LETTER_RE.test(t) || isDecDigit(t) || t === '_')) {
      text += advance()
      hadError = true
    }
    if (hadError) fail(start, `invalid number ${text}`)

    return { line: start.line, column: start.column, kind: 'number', body: text }
  }

  function scanString(start) {
    advance() // opening quote
    let value = ''
    for (;;) {
      const c = peek()
      if (c === undefined) fail(start, 'unterminated string')
      if (c === '\n') fail(here(), 'newline in string')
      if (c === '"') {
        advance()
        break
      }
      if (c === '\\') {
        const bpos = here()
        advance() // backslash
        const e = peek()
        if (e === undefined) continue // loop will report unterminated string
        if (e === 'n') {
          value += '\n'
          advance()
        } else if (e === 't') {
          value += '\t'
          advance()
        } else if (e === 'r') {
          value += '\r'
          advance()
        } else if (e === '\\') {
          value += '\\'
          advance()
        } else if (e === '"') {
          value += '"'
          advance()
        } else if (e === '0') {
          value += '\0'
          advance()
        } else if (e === 'x') {
          advance()
          const h1 = peek()
          const h2 = peek(1)
          if (isHexDigit(h1) && isHexDigit(h2)) {
            advance()
            advance()
            value += String.fromCharCode(parseInt(h1 + h2, 16))
          } else {
            fail(bpos, 'invalid escape \\x')
          }
        } else if (e === 'u') {
          advance()
          if (peek() === '{') {
            advance()
            let hex = ''
            while (isHexDigit(peek())) hex += advance()
            if (hex.length >= 1 && peek() === '}' && parseInt(hex, 16) <= 0x10ffff) {
              advance()
              value += String.fromCodePoint(parseInt(hex, 16))
            } else {
              fail(bpos, 'invalid escape \\u')
            }
          } else {
            fail(bpos, 'invalid escape \\u')
          }
        } else {
          fail(bpos, `invalid escape \\${e}`)
        }
        continue
      }
      value += advance()
    }
    return { line: start.line, column: start.column, kind: 'string', body: JSON.stringify(value) }
  }

  function scanRawString(start) {
    advance() // r
    advance() // opening quote
    let value = ''
    for (;;) {
      const c = peek()
      if (c === undefined) fail(start, 'unterminated string')
      if (c === '"') {
        advance()
        break
      }
      value += advance()
    }
    return { line: start.line, column: start.column, kind: 'rawstring', body: JSON.stringify(value) }
  }

  function scanPunct(start) {
    const c = peek()
    const two = c !== undefined && peek(1) !== undefined ? c + peek(1) : undefined
    if (two !== undefined && TWO_CHAR_PUNCT.has(two)) {
      advance()
      advance()
      return { line: start.line, column: start.column, kind: 'punct', body: two }
    }
    if (c !== undefined && ONE_CHAR_PUNCT.has(c)) {
      advance()
      return { line: start.line, column: start.column, kind: 'punct', body: c }
    }
    return null
  }

  const tokens = []
  for (;;) {
    for (;;) {
      const c = peek()
      if (c === undefined) break
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        advance()
        continue
      }
      if (c === '/' && peek(1) === '/') {
        advance()
        advance()
        while (peek() !== undefined && peek() !== '\n') advance()
        continue
      }
      if (c === '/' && peek(1) === '*') {
        const start = here()
        advance()
        advance()
        let depth = 1
        while (depth > 0) {
          if (peek() === undefined) fail(start, 'unterminated block comment')
          if (peek() === '/' && peek(1) === '*') {
            advance()
            advance()
            depth++
          } else if (peek() === '*' && peek(1) === '/') {
            advance()
            advance()
            depth--
          } else {
            advance()
          }
        }
        continue
      }
      break
    }

    const c = peek()
    if (c === undefined) break
    const start = here()

    if (c === 'r' && peek(1) === '"') {
      tokens.push(scanRawString(start))
      continue
    }
    if (IDENT_START_RE.test(c)) {
      let text = ''
      while (peek() !== undefined && IDENT_PART_RE.test(peek())) text += advance()
      const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
      tokens.push({ line: start.line, column: start.column, kind, body: text })
      continue
    }
    if (isDecDigit(c)) {
      tokens.push(scanNumber(start))
      continue
    }
    if (c === '"') {
      tokens.push(scanString(start))
      continue
    }
    const punct = scanPunct(start)
    if (punct !== null) {
      tokens.push(punct)
      continue
    }
    fail(start, `unexpected character ${c}`)
  }

  return tokens
}
"}

