 * `ParseError` carrying the line number and message the CLI reports.
 */

const NAME_PATTERN = /^[A-Za-z0-9_-]+$/
const COUNT_PATTERN = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

function fail(message, line) {
  throw new ParseError(message, line)
}

export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const candidates = new Set()
  let candidatesDeclared = false
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidatesDeclared || ballots.length > 0) {
        fail('candidates must be declared once, before any ballot', lineNumber)
      }
      const names = tokens.slice(1)
      if (names.length === 0) fail('expected candidates <name>...', lineNumber)
      for (const name of names) {
        if (!NAME_PATTERN.test(name)) fail(`invalid candidate name ${name}`, lineNumber)
        if (candidates.has(name)) fail(`candidate ${name} is declared twice`, lineNumber)
        candidates.add(name)
      }
      candidatesDeclared = true
      continue
    }

    if (directive === 'ballot') {
      if (!candidatesDeclared) {
        fail('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 3) fail('expected ballot <count> <candidate>...', lineNumber)
      const countToken = tokens[1]
      if (!COUNT_PATTERN.test(countToken)) fail('count must be a positive integer', lineNumber)
      const count = Number(countToken)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidates.has(name)) fail(`unknown candidate ${name}`, lineNumber)
        if (seen.has(name)) fail(`candidate ${name} is repeated`, lineNumber)
        seen.add(name)
      }
      ballots.push({ count, names })
      continue
    }

    fail(`unknown directive ${directive}`, lineNumber)
  }

  if (!candidatesDeclared) fail('no candidates', null)

  return { candidates: [...candidates], ballots }
}
"}

