{"file_path":"src/count.js","content":"/**
 * Runs the instant-runoff count described by an `{ candidates, ballots }`
 * election and returns every round counted plus the eventual winner.
 */

function pickEliminated(tied, rounds) {
  let current = tied
  if (current.length === 1) return current[0]

  let changed = true
  while (changed) {
    changed = false
    for (const round of rounds) {
      const values = current.map((name) => round.votes.get(name))
      const min = Math.min(...values)
      const max = Math.max(...values)
      if (min !== max) {
        current = current.filter((name) => round.votes.get(name) === min)
        changed = true
        break
      }
    }
    if (current.length === 1) return current[0]
  }

  return current.reduce((a, b) => (a > b ? a : b))
}

export function countElection(election) {
  const continuing = new Set(election.candidates)
  const rounds = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of election.ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) exhausted += ballot.count
      else votes.set(choice, votes.get(choice) + ballot.count)
    }

    const activeTotal = [...votes.values()].reduce((a, b) => a + b, 0)
    const round = { votes, exhausted, eliminated: null }
    rounds.push(round)

    if (activeTotal === 0) break

    const majority = [...votes.entries()].find(([, count]) => count * 2 > activeTotal)
    if (majority) {
      winner = majority[0]
      break
    }

    const min = Math.min(...votes.values())
    const tied = [...votes.entries()].filter(([, count]) => count === min).map(([name]) => name)
    const eliminated = pickEliminated(tied, rounds)
    round.eliminated = eliminated
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}
"}

