{"file_path":"src/format.js","content":"/**
 * Renders a counted election as the lines the `rounds` and `tally`
 * commands print to standard output.
 */

function formatRound(round, index) {
  const entries = [...round.votes.entries()].sort(([nameA, a], [nameB, b]) => {
    if (a !== b) return b - a
    return nameA < nameB ? -1 : 1
  })
  const parts = entries.map(([name, count]) => `${name}=${count}`)
  parts.push(`exhausted=${round.exhausted}`)
  const lines = [`round ${index + 1}: ${parts.join(' ')}`]
  if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  return lines
}

function winnerLine(winner) {
  return winner === null ? 'no winner' : `winner ${winner}`
}

export function formatRounds(result) {
  const lines = []
  result.rounds.forEach((round, index) => lines.push(...formatRound(round, index)))
  lines.push(winnerLine(result.winner))
  return lines.map((line) => line + '\n').join('')
}

export function formatTally(result) {
  return `rounds ${result.rounds.length}\n${winnerLine(result.winner)}\n`
}
"}

