 * Turn a cell's raw content into either a literal value or a parsed formula
 * AST (null when the formula body does not match the grammar).
 */
import { parseFormula, ParseError } from './parser.js'
import { parseLiteral } from './values.js'

export function compileCell(content) {
  if (content.startsWith('=')) {
    try {
      return { kind: 'formula', ast: parseFormula(content.slice(1)) }
    } catch (e) {
      if (e instanceof ParseError) return { kind: 'formula', ast: null }
      throw e
    }
  }
  return { kind: 'literal', value: parseLiteral(content) }
}
