 * Static (pre-evaluation) dependency listing: every cell a formula's parsed
 * AST names directly, ranges expanded.
 */
import { parseAddress, numToCol, compareAddresses } from './address.js'
import { compileCell } from './compile.js'

function addRange(set, fromWord, toWord) {
  const from = parseAddress(fromWord)
  const to = parseAddress(toWord)
  if (!from || !to) return
  const c1 = Math.min(from.col, to.col)
  const c2 = Math.max(from.col, to.col)
  const r1 = Math.min(from.row, to.row)
  const r2 = Math.max(from.row, to.row)
  for (let c = c1; c <= c2; c++) {
    for (let r = r1; r <= r2; r++) {
      set.add(numToCol(c) + r)
    }
  }
}

function walk(node, set) {
  switch (node.type) {
    case 'number':
    case 'boolean':
      return
    case 'address': {
      const parsed = parseAddress(node.word)
      if (parsed) set.add(parsed.address)
      return
    }
    case 'range':
      addRange(set, node.from, node.to)
      return
    case 'unary':
      walk(node.operand, set)
      return
    case 'binop':
      walk(node.left, set)
      walk(node.right, set)
      return
    case 'call':
      for (const arg of node.args) walk(arg, set)
      return
    default:
      throw new Error(`unknown node type ${node.type}`)
  }
}

/** Compute, for every declared cell, the sorted list of addresses its content names. */
export function computeDeps(cells) {
  const result = new Map()
  for (const [addr, content] of cells) {
    const compiled = compileCell(content)
    const set = new Set()
    if (compiled.kind === 'formula' && compiled.ast !== null) {
      walk(compiled.ast, set)
    }
    const addresses = [...set].map((a) => parseAddress(a))
    addresses.sort(compareAddresses)
    result.set(
      addr,
      addresses.map((a) => a.address)
    )
  }
  return result
}
"}

