      if (n === null || n < BigInt(min)) fail(`${name} must be an integer of at least ${min}`)
      return n
    }

    if (directive === 'bucket') {
      if (seenEvent) fail('declarations must come before the first event')
      if (parts.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
      const [, name, capacityStr, refillStr, perStr] = parts
      if (!isValidName(name)) fail(`invalid policy name ${name}`)
      if (policies.has(name)) fail(`policy ${name} is declared twice`)
      const capacity = field('capacity', capacityStr, 1)
      const refill = field('refill', refillStr, 0)
      const per = field('per', perStr, 1)
      policies.set(name, { type: 'bucket', capacity, refill, per })
    } else if (directive === 'window') {
      if (seenEvent) fail('declarations must come before the first event')
      if (parts.length !== 4) fail('expected window <name> <limit> <span>')
      const [, name, limitStr, spanStr] = parts
      if (!isValidName(name)) fail(`invalid policy name ${name}`)
      if (policies.has(name)) fail(`policy ${name} is declared twice`)
      const limit = field('limit', limitStr, 0)
      const span = field('span', spanStr, 1)
      policies.set(name, { type: 'window', limit, span })
    } else if (directive === 'route') {
      if (seenEvent) fail('declarations must come before the first event')
      if (parts.length < 3) fail('expected route <prefix> <policy>...')
      const prefix = parts[1]
      const policyNames = parts.slice(2)
      if (!isValidName(prefix)) fail(`invalid route prefix ${prefix}`)
      if (routePrefixes.has(prefix)) fail(`prefix ${prefix} is routed twice`)
      for (const pname of policyNames) {
        if (!policies.has(pname)) fail(`unknown policy ${pname}`)
      }
      routePrefixes.add(prefix)
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
      if (parts.length !== 3) fail('expected event <tick> <key>')
      const [, tickStr, key] = parts
      const tick = field('tick', tickStr, 0)
      if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
      if (!isValidName(key)) fail(`invalid key ${key}`)
      lastTick = tick
      seenEvent = true
      events.push({ tick, key })
    } else {
      fail(`unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}
"}

