{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-LShu2B/src/engine.js","content":"/**
 * Replays a parsed limiter file's event log against its routes and
 * policies, producing one verdict per event.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

function buildPolicyInstances(policies) {
  const instances = new Map()
  for (const [name, def] of policies) {
    instances.set(name, def.type === 'bucket' ? new TokenBucket(def) : new SlidingWindow(def))
  }
  return instances
}

/** The route whose prefix matches the key and is longest among matches, or null. */
function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix) && (best === null || route.prefix.length > best.prefix.length)) {
      best = route
    }
  }
  return best
}

/**
 * Runs every event in order, returning `{ tick, key, allowed, denyPolicy }`
 * per event. `denyPolicy` is the name of the first policy on the route that
 * refused, or null when the event was allowed.
 */
export function runEngine(model) {
  const instances = buildPolicyInstances(model.policies)
  const results = []

  for (const event of model.events) {
    const route = findRoute(model.routes, event.key)
    if (!route) {
      results.push({ tick: event.tick, key: event.key, allowed: true, denyPolicy: null })
      continue
    }

    const policies = route.policyNames.map((name) => instances.get(name))
    for (const policy of policies) policy.advance(event.key, event.tick)

    let denyPolicy = null
    for (let i = 0; i < policies.length; i++) {
      if (!policies[i].allow(event.key)) {
        denyPolicy = route.policyNames[i]
        break
      }
    }

    if (denyPolicy === null) {
      for (const policy of policies) {
        if (policy instanceof SlidingWindow) policy.record(event.key, event.tick)
        else policy.record(event.key)
      }
    }

    results.push({ tick: event.tick, key: event.key, allowed: denyPolicy === null, denyPolicy })
  }

  return results
}
"}

