    let child = node.map.get(seg)
    if (child === undefined) {
      child = { kind: 'table', map: new Map(), headerDefined: false }
      node.map.set(seg, child)
    } else if (child.kind === 'table') {
      // descend
    } else if (child.kind === 'array-of-tables') {
      child = child.value[child.value.length - 1]
    } else {
      throw new Fail(`${pathSoFar} is not a table`)
    }
    node = child
  }
  const last = segs[segs.length - 1]
  const path = segs.join('.')
  const existing = node.map.get(last)
  if (isArrayHeader) {
    let arrNode
    if (existing === undefined) {
      arrNode = { kind: 'array-of-tables', value: [] }
      node.map.set(last, arrNode)
    } else if (existing.kind === 'array-of-tables') {
      arrNode = existing
    } else {
      throw new Fail(`${path} is not an array of tables`)
    }
    const table = { kind: 'table', map: new Map(), headerDefined: false }
    arrNode.value.push(table)
    return table
  }
  if (existing === undefined) {
    const table = { kind: 'table', map: new Map(), headerDefined: true }
    node.map.set(last, table)
    return table
  }
  if (existing.kind === 'table') {
    if (existing.headerDefined) throw new Fail(`table ${path} is defined twice`)
    existing.headerDefined = true
    return existing
  }
