/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'
import { parseDocument } from './parser.js'
import { toJson, toKeys } from './format.js'
import { ParseError } from './errors.js'

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
    fail('error: usage: cli.js json|keys')
    return
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  let root
  try {
    root = parseDocument(lines)
  } catch (err) {
    if (err instanceof ParseError) {
      fail(`error: line ${err.line}: ${err.reason}`)
      return
    }
    throw err
  }

  const output = mode === 'json' ? toJson(root) : toKeys(root)
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

