 * The lexical scanner. `scan(source)` walks UTF-8 text (already decoded to a
 * JS string) and returns the list of tokens it finds, or throws a
 * `ScanError` at the first position the language rejects.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

const TAB_WIDTH = 4

function isLetter(c) {
  return c !== undefined && /[A-Za-z]/.test(c)
}

function isDecDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}

function isBinDigit(c) {
  return c === '0' || c === '1'
}

function isOctDigit(c) {
  return c !== undefined && c >= '0' && c <= '7'
}

function isIdentStart(c) {
  return c === '_' || isLetter(c)
}

function isIdentPart(c) {
  return c === '_' || isLetter(c) || isDecDigit(c)
}

function isNumTrailer(c) {
  return c === '_' || isLetter(c) || isDecDigit(c)
}

/** Raised at the first position the source violates the grammar. */
class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.scanError = true
    this.line = line
    this.col = col
  }
}

class Scanner {
  constructor(source) {
    this.chars = Array.from(source)
    this.pos = 0
    this.line = 1
    this.col = 1
  }

  atEnd() {
    return this.pos >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.pos + offset]
  }

  /** Consumes and returns the current character, updating line/column. */
  advance() {
    const c = this.chars[this.pos]
    this.pos += 1
    if (c === '\n') {
      this.line += 1
      this.col = 1
    } else if (c === '\t') {
      this.col = Math.floor((this.col - 1) / TAB_WIDTH + 1) * TAB_WIDTH + 1
    } else {
      this.col += 1
    }
    return c
  }

  fail(line, col, reason) {
    throw new ScanError(line, col, reason)
  }

  skipWhitespaceAndComments() {
    for (;;) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        while (!this.atEnd() && this.peek() !== '\n') this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        const startLine = this.line
        const startCol = this.col
        this.advance()
        this.advance()
        let depth = 1
        while (depth > 0) {
          if (this.atEnd()) this.fail(startLine, startCol, 'unterminated block comment')
          if (this.peek() === '/' && this.peek(1) === '*') {
            this.advance()
            this.advance()
            depth += 1
          } else if (this.peek() === '*' && this.peek(1) === '/') {
            this.advance()
            this.advance()
            depth -= 1
          } else {
            this.advance()
          }
        }
        continue
      }
      return
    }
  }

  /** Consumes a run of digits (per `isDigit`) with `_` allowed only between two digits. */
  consumeDigitRun(isDigit) {
    let text = ''
    let count = 0
    let lastWasDigit = false
    for (;;) {
      if (isDigit(this.peek())) {
        text += this.advance()
        lastWasDigit = true
        count += 1
      } else if (this.peek() === '_' && lastWasDigit && isDigit(this.peek(1))) {
        text += this.advance()
        lastWasDigit = false
      } else {
        break
      }
    }
    return { text, count }
  }

  consumeTrailer() {
    let text = ''
    while (isNumTrailer(this.peek())) text += this.advance()
    return text
  }

  scanNumber(startLine, startCol) {
    let text = ''
    let prefixError = false

    if (this.peek() === '0' && (this.peek(1) === 'x' || this.peek(1) === 'X')) {
      text += this.advance()
      text += this.advance()
      const run = this.consumeDigitRun(isHexDigit)
      text += run.text
      if (run.count === 0) prefixError = true
    } else if (this.peek() === '0' && (this.peek(1) === 'b' || this.peek(1) === 'B')) {
      text += this.advance()
      text += this.advance()
      const run = this.consumeDigitRun(isBinDigit)
      text += run.text
      if (run.count === 0) prefixError = true
    } else if (this.peek() === '0' && (this.peek(1) === 'o' || this.peek(1) === 'O')) {
      text += this.advance()
      text += this.advance()
      const run = this.consumeDigitRun(isOctDigit)
      text += run.text
      if (run.count === 0) prefixError = true
    } else {
      const intRun = this.consumeDigitRun(isDecDigit)
      text += intRun.text
      if (this.peek() === '.' && isDecDigit(this.peek(1))) {
        text += this.advance()
        text += this.consumeDigitRun(isDecDigit).text
      }
      if (
        (this.peek() === 'e' || this.peek() === 'E') &&
        (isDecDigit(this.peek(1)) || ((this.peek(1) === '+' || this.peek(1) === '-') && isDecDigit(this.peek(2))))
      ) {
        text += this.advance()
        if (this.peek() === '+' || this.peek() === '-') text += this.advance()
        text += this.consumeDigitRun(isDecDigit).text
      }
    }

    const trailer = this.consumeTrailer()
    if (prefixError || trailer.length > 0) {
      this.fail(startLine, startCol, `invalid number ${text}${trailer}`)
    }
    return text
  }

  scanIdent() {
    let text = ''
    while (isIdentPart(this.peek())) text += this.advance()
    return text
  }

  /** Reads one raw character that is legal inside a quoted string. */
  nextStringChar(openLine, openCol) {
    if (this.atEnd()) this.fail(openLine, openCol, 'unterminated string')
    if (this.peek() === '\n') this.fail(this.line, this.col, 'newline in string')
    return this.advance()
  }

  scanString(startLine, startCol) {
    this.advance() // opening quote
    let value = ''
    for (;;) {
      if (this.atEnd()) this.fail(startLine, startCol, 'unterminated string')
      if (this.peek() === '"') {
        this.advance()
        break
      }
      if (this.peek() === '\n') this.fail(this.line, this.col, 'newline in string')
      if (this.peek() === '\\') {
        const backslashLine = this.line
        const backslashCol = this.col
        this.advance()
        const e = this.nextStringChar(startLine, startCol)
        switch (e) {
          case 'n':
            value += '\n'
            break
          case 't':
            value += '\t'
            break
          case 'r':
            value += '\r'
            break
          case '\\':
            value += '\\'
            break
          case '"':
            value += '"'
            break
          case '0':
            value += '\0'
            break
          case 'x': {
            let hex = ''
            for (let i = 0; i < 2; i += 1) {
              const c = this.nextStringChar(startLine, startCol)
              if (!isHexDigit(c)) this.fail(backslashLine, backslashCol, 'invalid escape \\x')
              hex += c
            }
            value += String.fromCharCode(parseInt(hex, 16))
            break
          }
          case 'u': {
            const open = this.nextStringChar(startLine, startCol)
            if (open !== '{') this.fail(backslashLine, backslashCol, 'invalid escape \\u')
            let hex = ''
            for (;;) {
              const c = this.nextStringChar(startLine, startCol)
              if (c === '}') break
              if (!isHexDigit(c)) this.fail(backslashLine, backslashCol, 'invalid escape \\u')
              hex += c
            }
            if (hex.length === 0) this.fail(backslashLine, backslashCol, 'invalid escape \\u')
            const codePoint = parseInt(hex, 16)
            if (codePoint > 0x10ffff) this.fail(backslashLine, backslashCol, 'invalid escape \\u')
            value += String.fromCodePoint(codePoint)
            break
          }
          default:
            this.fail(backslashLine, backslashCol, `invalid escape \\${e}`)
        }
      } else {
        value += this.advance()
      }
    }
    return value
  }

  scanRawString(startLine, startCol) {
    this.advance() // 'r'
    this.advance() // opening quote
    let value = ''
    for (;;) {
      if (this.atEnd()) this.fail(startLine, startCol, 'unterminated string')
      if (this.peek() === '"') {
        this.advance()
        break
      }
      value += this.advance()
    }
    return value
  }

  scanPunct(startLine, startCol) {
    const two = (this.peek() ?? '') + (this.peek(1) ?? '')
    if (TWO_CHAR_PUNCT.has(two)) {
      this.advance()
      this.advance()
      return two
    }
    const one = this.peek()
    if (ONE_CHAR_PUNCT.has(one)) {
      this.advance()
      return one
    }
    this.fail(startLine, startCol, `unexpected character ${one}`)
    return undefined
  }

  next() {
    this.skipWhitespaceAndComments()
    if (this.atEnd()) return null

    const line = this.line
    const col = this.col
    const c = this.peek()

    if (isDecDigit(c)) {
      const text = this.scanNumber(line, col)
      return { line, col, kind: 'number', text, value: text }
    }
    if (c === '"') {
      const value = this.scanString(line, col)
      return { line, col, kind: 'string', text: value, value }
    }
    if (c === 'r' && this.peek(1) === '"') {
      const value = this.scanRawString(line, col)
      return { line, col, kind: 'rawstring', text: value, value }
    }
    if (isIdentStart(c)) {
      const text = this.scanIdent()
      const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
      return { line, col, kind, text, value: text }
    }
    const text = this.scanPunct(line, col)
    return { line, col, kind: 'punct', text, value: text }
  }
}

export function scan(source) {
  const scanner = new Scanner(source)
  const tokens = []
  for (;;) {
    const token = scanner.next()
    if (token === null) break
    tokens.push(token)
  }
  return tokens
}
"}

