/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { scan } from './scanner.js'

const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function usageError() {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

async function readStdin() {
  process.stdin.setEncoding('utf8')
  let input = ''
  for await (const chunk of process.stdin) input += chunk
  return input
}

function tokenBody(token) {
  if (token.kind === 'string' || token.kind === 'rawstring') return JSON.stringify(token.value)
  return token.text
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'tokens' && mode !== 'stats')) {
    usageError()
    return
  }

  const source = await readStdin()

  let tokens
  try {
    tokens = scan(source)
  } catch (error) {
    if (error && error.scanError) {
      process.stderr.write(`error: ${error.line}:${error.col}: ${error.message}\n`)
      process.exit(2)
      return
    }
    throw error
  }

  if (mode === 'tokens') {
    let out = ''
    for (const token of tokens) {
      out += `${token.line}:${token.col} ${token.kind} ${tokenBody(token)}\n`
    }
    process.stdout.write(out)
  } else {
    const counts = Object.fromEntries(KINDS.map((k) => [k, 0]))
    for (const token of tokens) counts[token.kind] += 1
    let out = ''
    for (const kind of KINDS) out += `${kind} ${counts[kind]}\n`
    out += `total ${tokens.length}\n`
    process.stdout.write(out)
  }
}

main()
"}

