 * Renders the outcome of `runElection` into the exact text the `rounds` and
 * `tally` modes print to standard output.
 */

function sortedEntries(votes) {
  return [...votes.entries()].sort(([nameA, countA], [nameB, countB]) => {
    if (countA !== countB) return countA < countB ? 1 : -1
    return nameA < nameB ? -1 : nameA > nameB ? 1 : 0
  })
}

function outcomeLine(winner) {
  return winner === null ? 'no winner' : `winner ${winner}`
}

/**
 * @param {{ rounds: object[], winner: string | null }} result
 * @returns {string}
 */
export function formatRounds(result) {
  const lines = []
  result.rounds.forEach((round, index) => {
    const entries = sortedEntries(round.votes)
      .map(([name, count]) => `${name}=${count}`)
      .join(' ')
    lines.push(`round ${index + 1}: ${entries} exhausted=${round.exhausted}`)
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  })
  lines.push(outcomeLine(result.winner))
  return lines.map((line) => line + '\n').join('')
}

/**
 * @param {{ rounds: object[], winner: string | null }} result
 * @returns {string}
 */
export function formatTally(result) {
  return `rounds ${result.rounds.length}\n${outcomeLine(result.winner)}\n`
}
"}

