{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-dOCsSC/src/diff.js","content":"/**
 * Whole-line diffing of one side against the base, following the exact
 * longest-common-subsequence tie-breaking rule the specification describes:
 * walking both documents from the start, take a match whenever the current
 * lines are equal, and otherwise advance the side whose remaining
 * subsequence is at least as long as the other's, preferring to advance the
 * base when they tie.
 */

/**
 * Builds the table `lcs[i][j]` holding the length of the longest common
 * subsequence of `base[i:]` and `other[j:]`.
 */
function lcsLengths(base, other) {
  const n = base.length
  const m = other.length
  const lcs = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      lcs[i][j] = base[i] === other[j] ? lcs[i + 1][j + 1] + 1 : Math.max(lcs[i + 1][j], lcs[i][j + 1])
    }
  }
  return lcs
}

/**
 * Walks the LCS table from the start, producing the matched index pairs in
 * increasing order.
 */
function matchPairs(base, other) {
  const lcs = lcsLengths(base, other)
  const pairs = []
  let i = 0
  let j = 0
  while (i < base.length && j < other.length) {
    if (base[i] === other[j]) {
      pairs.push([i, j])
      i++
      j++
    } else if (lcs[i + 1][j] >= lcs[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return pairs
}

/**
 * Describes how `other` differs from `base` as a list of changes, each one a
 * run of base lines (`baseStart`..`baseEnd`) replaced by a run of `other`'s
 * lines (`otherStart`..`otherEnd`). An insertion has an empty base run and a
 * deletion an empty other run.
 */
export function diffChanges(base, other) {
  const pairs = matchPairs(base, other)
  const changes = []
  let baseCursor = 0
  let otherCursor = 0

  for (const [i, j] of pairs) {
    if (i > baseCursor || j > otherCursor) {
      changes.push({ baseStart: baseCursor, baseEnd: i, otherStart: otherCursor, otherEnd: j })
    }
    baseCursor = i + 1
    otherCursor = j + 1
  }
  if (baseCursor < base.length || otherCursor < other.length) {
    changes.push({ baseStart: baseCursor, baseEnd: base.length, otherStart: otherCursor, otherEnd: other.length })
  }
  return changes
}
"}

