function linesEqual(a, b) {
  if (a.length !== b.length) return false
  for (let k = 0; k < a.length; k++) if (a[k] !== b[k]) return false
  return true
}

/**
 * Groups the changes from both sides into regions: a region runs from the
 * base start of its first change to the base end of the last change that
 * overlaps it, absorbing further changes that start at or before the
 * region's current end. Base lines outside every region are stable.
 */
function buildRegions(mineChanges, theirsChanges, baseLength) {
  const all = mineChanges
    .map(change => ({ ...change, side: 'mine' }))
    .concat(theirsChanges.map(change => ({ ...change, side: 'theirs' })))
    .sort((a, b) => a.baseStart - b.baseStart || (a.side === 'mine' ? -1 : 1))

  const regions = []
  let i = 0
  while (i < all.length) {
    const members = [all[i]]
    let start = all[i].baseStart
    let end = all[i].baseEnd
    i++
    while (i < all.length && all[i].baseStart <= end) {
      end = Math.max(end, all[i].baseEnd)
      members.push(all[i])
      i++
    }
    regions.push({ start, end, members })
  }

  const segments = []
  let cursor = 0
  for (const region of regions) {
    if (region.start > cursor) segments.push({ type: 'stable', start: cursor, end: region.start })
    segments.push({ type: 'region', ...region })
    cursor = region.end
  }
  if (cursor < baseLength) segments.push({ type: 'stable', start: cursor, end: baseLength })
  return segments
}

/**
 * Computes a side's lines for a region: the region's own document slice as
 * that side sees it, expanded (from the smallest start of its own changes
 * touching the region to the largest end) to cover the whole region even
 * where that side made no change of its own within it.
 */
function sideLines(region, changesOfSide, sideDoc, baseDoc) {
  if (changesOfSide.length === 0) return baseDoc.slice(region.start, region.end)

  const ownBaseStart = Math.min(...changesOfSide.map(change => change.baseStart))
  const ownBaseEnd = Math.max(...changesOfSide.map(change => change.baseEnd))
  const first = changesOfSide.find(change => change.baseStart === ownBaseStart)
  const last = changesOfSide.reduce((a, b) => (b.baseEnd > a.baseEnd ? b : a))

  const start = first.otherStart - (ownBaseStart - region.start)
  const end = last.otherEnd + (region.end - ownBaseEnd)
  return sideDoc.slice(start, end)
}

/**
 * Resolves a region given its computed mine/base/theirs line slices,
 * following the specification's precedence: agreement on both sides wins,
 * then a side that reverted to the base defers to the other, and anything
 * left is a conflict.
 */
function resolveRegion(mine, base, theirs) {
  if (linesEqual(mine, theirs)) return { kind: 'both', lines: mine }
  if (linesEqual(mine, base)) return { kind: 'theirs', lines: theirs }
  if (linesEqual(theirs, base)) return { kind: 'mine', lines: mine }
  return { kind: 'conflict', mine, base, theirs }
}

/**
 * Produces the ordered list of stable spans and resolved/conflicting regions
 * describing the three-way merge of `mine` and `theirs` against `base`.
 */
export function computeMerge(mine, base, theirs) {
  const mineChanges = diffChanges(base, mine)
  const theirsChanges = diffChanges(base, theirs)
  const segments = buildRegions(mineChanges, theirsChanges, base.length)

  return segments.map(segment => {
    if (segment.type === 'stable') return { type: 'stable', lines: base.slice(segment.start, segment.end) }

    const mineOfRegion = segment.members.filter(change => change.side === 'mine')
    const theirsOfRegion = segment.members.filter(change => change.side === 'theirs')
    const mineLines = sideLines(segment, mineOfRegion, mine, base)
    const theirsLines = sideLines(segment, theirsOfRegion, theirs, base)
    const baseLines = base.slice(segment.start, segment.end)

    return { type: 'region', ...resolveRegion(mineLines, baseLines, theirsLines) }
  })
}
"}

