{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-dOCsSC/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */
import { readFileSync } from 'node:fs'
import { parseInput } from './parse.js'
import { computeMerge } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (!MODES.has(mode)) fail('error: usage: cli.js merge|merge2|regions')

const input = readFileSync(0, 'utf8')
const parts = parseInput(input)
if (parts === null) fail('error: expected three parts separated by %%%')

const [mine, base, theirs] = parts
const segments = computeMerge(mine, base, theirs)

let conflict = false
const out = []

function writeLines(lines) {
  for (const line of lines) out.push(`${line}\n`)
}

for (const segment of segments) {
  if (segment.type === 'stable' || segment.kind !== 'conflict') {
    writeLines(segment.lines)
    continue
  }

  conflict = true
  if (mode === 'regions') {
    out.push(`conflict mine=${segment.mine.length} base=${segment.base.length} theirs=${segment.theirs.length}\n`)
    continue
  }

  out.push('<<<<<<< mine\n')
  writeLines(segment.mine)
  if (mode === 'merge') {
    out.push('||||||| base\n')
    writeLines(segment.base)
  }
  out.push('=======\n')
  writeLines(segment.theirs)
  out.push('>>>>>>> theirs\n')
}

if (mode === 'regions') {
  const regionOut = []
  for (const segment of segments) {
    if (segment.type === 'stable') regionOut.push(`stable ${segment.lines.length}\n`)
    else if (segment.kind === 'conflict') {
      regionOut.push(`conflict mine=${segment.mine.length} base=${segment.base.length} theirs=${segment.theirs.length}\n`)
    } else regionOut.push(`${segment.kind} ${segment.lines.length}\n`)
  }
  process.stdout.write(regionOut.join(''))
} else {
  process.stdout.write(out.join(''))
}

process.exit(conflict ? 1 : 0)
"}

