{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-j68tDP/src/simulate.js","content":"import { LimiterError } from './errors.js'
import { isValidToken, parseIntField } from './tokens.js'
import { BucketPolicy, WindowPolicy } from './policies.js'

/** Splits stdin into lines, dropping the empty tail a trailing newline leaves. */
function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Parses and replays a limiter file in one pass. Parsing, declaration
 * bookkeeping and event simulation all happen line by line so that the first
 * offending line is always the one reported, and nothing is ever emitted
 * unless the whole file parses.
 */
export function runLimiter(text) {
  const lines = splitLines(text)

  const policies = new Map()
  const routes = new Map()
  let sawEvent = false
  let lastTick = null

  const replayLines = []
  const perKey = new Map()
  const keyOrder = []
  let totalAllowed = 0
  let totalDenied = 0

  function findRoute(key) {
    let best = null
    for (const [prefix, policyNames] of routes) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.prefix.length)) {
        best = { prefix, policyNames }
      }
    }
    return best
  }

  function recordVerdict(key, allowed) {
    let counts = perKey.get(key)
    if (counts === undefined) {
      counts = { allowed: 0, denied: 0 }
      perKey.set(key, counts)
      keyOrder.push(key)
    }
    if (allowed) {
      counts.allowed++
      totalAllowed++
    } else {
      counts.denied++
      totalDenied++
    }
  }

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket') {
      if (sawEvent) throw new LimiterError('declarations must come before the first event', lineNo)
      if (tokens.length !== 5) {
        throw new LimiterError('expected bucket <name> <capacity> <refill> <per>', lineNo)
      }
      const [, name, capacityStr, refillStr, perStr] = tokens
      if (!isValidToken(name)) throw new LimiterError(`invalid policy name ${name}`, lineNo)
      const capacity = parseIntField(capacityStr, 'capacity', 1, lineNo)
      const refill = parseIntField(refillStr, 'refill', 0, lineNo)
      const per = parseIntField(perStr, 'per', 1, lineNo)
      if (policies.has(name)) throw new LimiterError(`policy ${name} is declared twice`, lineNo)
      policies.set(name, new BucketPolicy(name, capacity, refill, per))
    } else if (directive === 'window') {
      if (sawEvent) throw new LimiterError('declarations must come before the first event', lineNo)
      if (tokens.length !== 4) {
        throw new LimiterError('expected window <name> <limit> <span>', lineNo)
      }
      const [, name, limitStr, spanStr] = tokens
      if (!isValidToken(name)) throw new LimiterError(`invalid policy name ${name}`, lineNo)
      const limit = parseIntField(limitStr, 'limit', 0, lineNo)
      const span = parseIntField(spanStr, 'span', 1, lineNo)
      if (policies.has(name)) throw new LimiterError(`policy ${name} is declared twice`, lineNo)
      policies.set(name, new WindowPolicy(name, limit, span))
    } else if (directive === 'route') {
      if (sawEvent) throw new LimiterError('declarations must come before the first event', lineNo)
      if (tokens.length < 3) {
        throw new LimiterError('expected route <prefix> <policy>...', lineNo)
      }
      const prefix = tokens[1]
      if (!isValidToken(prefix)) throw new LimiterError(`invalid route prefix ${prefix}`, lineNo)
      const policyNames = tokens.slice(2)
      for (const name of policyNames) {
        if (!policies.has(name)) throw new LimiterError(`unknown policy ${name}`, lineNo)
      }
      if (routes.has(prefix)) throw new LimiterError(`prefix ${prefix} is routed twice`, lineNo)
      routes.set(prefix, policyNames)
    } else if (directive === 'event') {
      if (tokens.length !== 3) {
        throw new LimiterError('expected event <tick> <key>', lineNo)
      }
      const [, tickStr, key] = tokens
      const tick = parseIntField(tickStr, 'tick', 0, lineNo)
      if (!isValidToken(key)) throw new LimiterError(`invalid key ${key}`, lineNo)
      if (lastTick !== null && tick < lastTick) {
        throw new LimiterError(`tick ${tick} is before tick ${lastTick}`, lineNo)
      }
      lastTick = tick
      sawEvent = true

      const route = findRoute(key)
      if (route === null) {
        replayLines.push(`${tick} ${key} allow`)
        recordVerdict(key, true)
        continue
      }
      const routePolicies = route.policyNames.map((name) => policies.get(name))
      for (const policy of routePolicies) policy.advance(key, tick)
      let denier = null
      for (const policy of routePolicies) {
        if (!policy.allows(key)) {
          denier = policy.name
          break
        }
      }
      if (denier === null) {
        for (const policy of routePolicies) policy.record(key, tick)
        replayLines.push(`${tick} ${key} allow`)
        recordVerdict(key, true)
      } else {
        replayLines.push(`${tick} ${key} deny ${denier}`)
        recordVerdict(key, false)
      }
    } else {
      throw new LimiterError(`unknown directive ${directive}`, lineNo)
    }
  }

  return { replayLines, perKey, keyOrder, totalAllowed, totalDenied }
}
"}

