 * URI reference parsing, normalization and resolution, implementing the
 * generic syntax and algorithms of RFC 3986.
 */

const DEFAULT_PORTS = { http: '80', https: '443', ws: '80', wss: '443', ftp: '21' }

/** Thrown when a `%` is not followed by two hexadecimal digits. */
export class UriError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

/**
 * Splits a URI reference into scheme, authority, path, query and fragment,
 * per RFC 3986's generic syntax. An absent component is `null`; the
 * authority, when present, is `{ userinfo, host, port }` with the same
 * absent/empty distinction on each of those three.
 */
export function parseReference(s) {
  let rest = s
  let scheme = null
  const schemeEnd = rest.search(/[:/?#]/)
  if (schemeEnd !== -1 && rest[schemeEnd] === ':') {
    scheme = rest.slice(0, schemeEnd)
    rest = rest.slice(schemeEnd + 1)
  }

  let authority = null
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    const authorityEnd = rest.search(/[/?#]/)
    let authorityText
    if (authorityEnd === -1) {
      authorityText = rest
      rest = ''
    } else {
      authorityText = rest.slice(0, authorityEnd)
      rest = rest.slice(authorityEnd)
    }
    authority = parseAuthority(authorityText)
  }

  const pathEnd = rest.search(/[?#]/)
  let path
  if (pathEnd === -1) {
    path = rest
    rest = ''
  } else {
    path = rest.slice(0, pathEnd)
    rest = rest.slice(pathEnd)
  }

  let query = null
  if (rest.startsWith('?')) {
    const fragmentStart = rest.indexOf('#')
    if (fragmentStart === -1) {
      query = rest.slice(1)
      rest = ''
    } else {
      query = rest.slice(1, fragmentStart)
      rest = rest.slice(fragmentStart)
    }
  }

  let fragment = null
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

/**
 * Splits an authority string into userinfo, host and port: the userinfo is
 * everything before the last `@`, the port is everything after the first
 * `:` that follows the last `]`, and the host is what lies between.
 */
function parseAuthority(text) {
  let userinfo = null
  let hostAndPort = text
  const at = text.lastIndexOf('@')
  if (at !== -1) {
    userinfo = text.slice(0, at)
    hostAndPort = text.slice(at + 1)
  }

  const bracket = hostAndPort.lastIndexOf(']')
  const colon = hostAndPort.indexOf(':', bracket === -1 ? 0 : bracket)
  let host
  let port = null
  if (colon !== -1) {
    host = hostAndPort.slice(0, colon)
    port = hostAndPort.slice(colon + 1)
  } else {
    host = hostAndPort
  }

  return { userinfo, host, port }
}

/** Joins parsed components back into a URI reference string. */
export function serialize(u) {
  let out = ''
  if (u.scheme !== null) out += u.scheme + ':'
  if (u.authority !== null) {
    out += '//'
    if (u.authority.userinfo !== null) out += u.authority.userinfo + '@'
    out += u.authority.host
    if (u.authority.port !== null) out += ':' + u.authority.port
  }
  out += u.path
  if (u.query !== null) out += '?' + u.query
  if (u.fragment !== null) out += '#' + u.fragment
  return out
}

function isAsciiUpper(code) {
  return code >= 0x41 && code <= 0x5a
}

/** Lowercases ASCII letters only, leaving every other character untouched. */
function asciiLower(s) {
  return s.replace(/[A-Z]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 0x20))
}

function isUnreserved(code) {
  return (
    (code >= 0x41 && code <= 0x5a) || // A-Z
    (code >= 0x61 && code <= 0x7a) || // a-z
    (code >= 0x30 && code <= 0x39) || // 0-9
    code === 0x2d || // -
    code === 0x2e || // .
    code === 0x5f || // _
    code === 0x7e // ~
  )
}

const HEX_PAIR = /^[0-9a-fA-F]{2}$/

/**
 * Uppercases the hex digits of every `%XX` triplet in a component, then
 * decodes the triplets that encode an unreserved character.
 */
function normalizePercent(s, component) {
  if (s === null) return null
  let out = ''
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '%') {
      const hex = s.slice(i + 1, i + 3)
      if (!HEX_PAIR.test(hex)) throw new UriError(component)
      const upper = hex.toUpperCase()
      const code = parseInt(upper, 16)
      out += isUnreserved(code) ? String.fromCharCode(code) : '%' + upper
      i += 2
    } else {
      out += s[i]
    }
  }
  return out
}

/** Removes `.` and `..` path segments per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  const output = []
  let input = path
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output.pop()
    } else if (input === '/..') {
      input = '/'
      output.pop()
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const match = /^\/?[^/]*/.exec(input)
      const segment = match[0]
      input = input.slice(segment.length)
      output.push(segment)
    }
  }
  return output.join('')
}

/**
 * Normalizes a parsed URI reference: lowercases the scheme, decodes
 * unreserved percent-encodings and uppercases the rest, lowercases the
 * host, drops a default or empty port, removes dot segments from the path,
 * and roots an empty path when an authority is present.
 */
export function normalize(u) {
  const scheme = u.scheme !== null ? asciiLower(u.scheme) : null

  let authority = null
  if (u.authority !== null) {
    const userinfo = normalizePercent(u.authority.userinfo, 'userinfo')
    let host = normalizePercent(u.authority.host, 'host')
    host = asciiLower(host)
    let port = u.authority.port
    if (port === '' || (port !== null && scheme !== null && DEFAULT_PORTS[scheme] === port)) {
      port = null
    }
    authority = { userinfo, host, port }
  }

  let path = normalizePercent(u.path, 'path')
  const query = normalizePercent(u.query, 'query')
  const fragment = normalizePercent(u.fragment, 'fragment')

  path = removeDotSegments(path)
  if (authority !== null && path === '') path = '/'

  return { scheme, authority, path, query, fragment }
}

function mergePaths(base, referencePath) {
  if (base.authority !== null && base.path === '') {
    return '/' + referencePath
  }
  const lastSlash = base.path.lastIndexOf('/')
  if (lastSlash === -1) return referencePath
  return base.path.slice(0, lastSlash + 1) + referencePath
}

/**
 * Resolves a reference against a base URI per RFC 3986 section 5.2.2, in
 * its strict form (a reference that repeats the base's scheme is still
 * treated as an absolute URI). Returns an unnormalized parsed structure.
 */
export function resolveReference(base, reference) {
  let scheme, authority, path, query
  if (reference.scheme !== null) {
    scheme = reference.scheme
    authority = reference.authority
    path = removeDotSegments(reference.path)
    query = reference.query
  } else if (reference.authority !== null) {
    scheme = base.scheme
    authority = reference.authority
    path = removeDotSegments(reference.path)
    query = reference.query
  } else if (reference.path === '') {
    scheme = base.scheme
    authority = base.authority
    path = base.path
    query = reference.query !== null ? reference.query : base.query
  } else {
    scheme = base.scheme
    authority = base.authority
    if (reference.path.startsWith('/')) {
      path = removeDotSegments(reference.path)
    } else {
      path = removeDotSegments(mergePaths(base, reference.path))
    }
    query = reference.query
  }
  return { scheme, authority, path, query, fragment: reference.fragment }
}
"}

