/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parseReference, normalize, resolveReference, serialize, UriError } from './uri.js'

function splitRecords(text) {
  if (text === '') return []
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

class LineError extends Error {}

function processNormalize(line) {
  const parsed = parseReference(line)
  return serialize(normalize(parsed))
}

function processResolve(line) {
  const space = line.indexOf(' ')
  if (space === -1) throw new LineError('expected a base and a reference')
  const baseText = line.slice(0, space)
  const referenceText = line.slice(space + 1)
  const base = parseReference(baseText)
  if (base.scheme === null) throw new LineError('the base has no scheme')
  const reference = parseReference(referenceText)
  const resolved = resolveReference(base, reference)
  return serialize(normalize(resolved))
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const mode = args[0]
  const process1 = mode === 'normalize' ? processNormalize : processResolve

  const input = require('node:fs').readFileSync(0, 'utf8')
  const records = splitRecords(input)

  const results = []
  for (let i = 0; i < records.length; i++) {
    const lineNumber = i + 1
    try {
      results.push(process1(records[i]))
    } catch (error) {
      const message = error instanceof UriError ? error.message : error instanceof LineError ? error.message : null
      if (message === null) throw error
      process.stderr.write(`error: line ${lineNumber}: ${message}\n`)
      process.exit(2)
    }
  }

  process.stdout.write(results.map((r) => r + '\n').join(''))
  process.exit(0)
}

main()
"}

