  const tok = peek(state)
  if (tok && tok.type === 'op' && (tok.value === '-' || tok.value === '+')) {
    state.pos++
    const operand = parsePrimary(state)
    if (operand === null) return null
    return { type: 'unary', op: tok.value, operand }
  }
  return parsePrimary(state)
}

function parsePrimary(state) {
  const tok = peek(state)
  if (!tok) return null

  if (tok.type === 'number') {
    state.pos++
    return { type: 'number', value: Number(tok.value) }
  }

  if (tok.type === 'op' && tok.value === '(') {
    state.pos++
    const inner = parseComparison(state)
    if (inner === null) return null
    if (!takeOp(state, ')')) return null
    return inner
  }

  if (tok.type === 'word') {
    state.pos++
    const upper = tok.value.toUpperCase()

    if (peek(state) && peek(state).type === 'op' && peek(state).value === '(') {
