  const tok = peek(state)
  if (tok && tok.type === 'op' && tok.value === ')') return []

  const args = []
  for (;;) {
    const arg = parseComparison(state)
    if (arg === null) return null
    args.push(arg)
    if (!takeOp(state, ',')) break
  }
  return args
}
"}

