export function formatValue(value) {
  switch (value.type) {
    case 'number':
      return formatNumber(value.value)
    case 'text':
      return value.value
    case 'boolean':
      return value.value ? 'TRUE' : 'FALSE'
    case 'error':
      return value.value
    default:
