{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-rFei4S/src/evaluate.js","content":"/**
 * Cell evaluation: formula parsing (cached per cell), arithmetic and
 * comparison semantics, the built-in functions, and cycle detection.
 */

import { parseFormula } from './parser.js'
import { parseLiteral } from './literal.js'
import { parseAddress, compareAddresses, columnIndexToLetters } from './address.js'
import { num, bool, err, toNumber, finiteNumber, compareValues } from './values.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const AGGREGATE_FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'AVG', 'COUNT'])

/**
 * Builds an evaluator over a parsed sheet (as produced by `parseSheet`).
 * `getValue(key)` computes and memoizes the value of the cell named by a
 * canonical address key such as `A1`.
 */
export function createEvaluator(cells) {
  const astCache = new Map()
  const valueCache = new Map()
  const inProgress = new Set()

  function contentOf(key) {
    const cell = cells.get(key)
    return cell ? cell.content : ''
  }

  function astOf(key) {
    if (astCache.has(key)) return astCache.get(key)
    const content = contentOf(key)
    const ast = content.startsWith('=') ? parseFormula(content.slice(1)) : null
    astCache.set(key, ast)
    return ast
  }

  function getValue(key) {
    if (valueCache.has(key)) return valueCache.get(key)
    if (inProgress.has(key)) return err('#CYCLE!')

    inProgress.add(key)
    const content = contentOf(key)
    let result
    if (content.startsWith('=')) {
      const ast = astOf(key)
      result = ast === null ? err('#ERR!') : evaluateNode(ast)
    } else {
      result = parseLiteral(content)
    }
    inProgress.delete(key)
    valueCache.set(key, result)
    return result
  }

  function resolveAddress(token) {
    const parsed = parseAddress(token)
    return parsed ? getValue(parsed.key) : err('#REF!')
  }

  function evaluateNode(node) {
    switch (node.type) {
      case 'number':
        return num(node.value)
      case 'bool':
        return bool(node.value)
      case 'address':
        return resolveAddress(node.token)
      case 'range':
        // Reached outside the one place a range is legal: directly as a
        // function argument. `evalCall` handles that case separately and
        // never calls back in here with a range node.
        return err('#ERR!')
      case 'unary':
        return evalUnary(node)
      case 'binary':
        return evalBinary(node)
      case 'call':
        return evalCall(node)
      default:
        throw new Error(`unreachable node type: ${node.type}`)
    }
  }

  function evalUnary(node) {
    const operand = evaluateNode(node.operand)
    if (operand.type === 'error') return operand
    const n = toNumber(operand)
    if (n.type === 'error') return n
    return finiteNumber(node.op === '-' ? -n.value : n.value)
  }

  function evalBinary(node) {
    const left = evaluateNode(node.left)
    if (left.type === 'error') return left
    const right = evaluateNode(node.right)
    if (right.type === 'error') return right

    if (COMPARISON_OPS.has(node.op)) {
      const cmp = compareValues(left, right)
      switch (node.op) {
        case '=':
          return bool(cmp === 0)
        case '<>':
          return bool(cmp !== 0)
        case '<':
          return bool(cmp < 0)
        case '<=':
          return bool(cmp <= 0)
        case '>':
          return bool(cmp > 0)
        case '>=':
          return bool(cmp >= 0)
      }
    }

    const ln = toNumber(left)
    if (ln.type === 'error') return ln
    const rn = toNumber(right)
    if (rn.type === 'error') return rn

    switch (node.op) {
      case '+':
        return finiteNumber(ln.value + rn.value)
      case '-':
        return finiteNumber(ln.value - rn.value)
      case '*':
        return finiteNumber(ln.value * rn.value)
      case '/':
        return rn.value === 0 ? err('#DIV/0!') : finiteNumber(ln.value / rn.value)
      case '^':
        return finiteNumber(Math.pow(ln.value, rn.value))
      default:
        throw new Error(`unreachable operator: ${node.op}`)
    }
  }

  /** Expands a range node into its covered cell keys, column asc then row asc. */
  function expandRange(node) {
    const from = parseAddress(node.from)
    const to = parseAddress(node.to)
    if (!from || !to) return null

    const minCol = Math.min(from.column, to.column)
    const maxCol = Math.max(from.column, to.column)
    const minRow = Math.min(from.row, to.row)
    const maxRow = Math.max(from.row, to.row)

    const addresses = []
    for (let col = minCol; col <= maxCol; col++) {
      for (let row = minRow; row <= maxRow; row++) {
        addresses.push({ column: col, row })
      }
    }
    addresses.sort(compareAddresses)
    return addresses.map((a) => columnIndexToLetters(a.column) + a.row)
  }

  /** Evaluates a function argument list, expanding direct range arguments. */
  function flattenArgs(args) {
    const values = []
    for (const arg of args) {
      if (arg.type === 'range') {
        const keys = expandRange(arg)
        if (keys === null) {
          values.push(err('#REF!'))
        } else {
          for (const key of keys) values.push(getValue(key))
        }
      } else {
        values.push(evaluateNode(arg))
      }
    }
    return values
  }

  function firstError(values) {
    for (const v of values) {
      if (v.type === 'error') return v
    }
    return null
  }

  function evalCall(node) {
    const { name, args } = node

    if (name === 'ABS') {
      if (args.length !== 1) return err('#ERR!')
      const v = evaluateNode(args[0])
      if (v.type === 'error') return v
      const n = toNumber(v)
      if (n.type === 'error') return n
      return finiteNumber(Math.abs(n.value))
    }

    if (name === 'IF') {
      if (args.length !== 3) return err('#ERR!')
      const [condNode, thenNode, elseNode] = args
      const cond = evaluateNode(condNode)
      if (cond.type === 'error') return cond
      if (cond.type === 'text') return err('#VALUE!')
      const truth = cond.type === 'boolean' ? cond.value : cond.value !== 0
      return evaluateNode(truth ? thenNode : elseNode)
    }

    if (AGGREGATE_FUNCTIONS.has(name)) {
      if (args.length < 1) return err('#ERR!')
      const values = flattenArgs(args)
      const errValue = firstError(values)
      if (errValue) return errValue

      if (name === 'COUNT') {
        return num(values.filter((v) => v.type === 'number').length)
      }

      const numbers = []
      for (const v of values) {
