 * Collecting the cells a parsed formula names directly, for `deps` mode.
 *
 * Every address and range in the AST counts, regardless of whether the
 * formula would actually evaluate that branch or whether a range sits in a
 * legal (direct function argument) or illegal position: the spec only
 * excludes formulas the grammar rejects outright.
 */

import { parseAddress, compareAddresses, columnIndexToLetters } from './address.js'

export function collectDependencies(ast) {
  const found = new Map()

  function addKey(parsed) {
    if (!parsed) return
    if (!found.has(parsed.key)) found.set(parsed.key, parsed)
  }

  function visit(node) {
    switch (node.type) {
      case 'number':
      case 'bool':
        return
      case 'address':
        addKey(parseAddress(node.token))
        return
      case 'range': {
        const from = parseAddress(node.from)
        const to = parseAddress(node.to)
        if (!from || !to) return
        const minCol = Math.min(from.column, to.column)
        const maxCol = Math.max(from.column, to.column)
        const minRow = Math.min(from.row, to.row)
        const maxRow = Math.max(from.row, to.row)
        for (let col = minCol; col <= maxCol; col++) {
          for (let row = minRow; row <= maxRow; row++) {
            addKey(parseAddress(columnIndexToLetters(col) + row))
          }
        }
        return
      }
      case 'unary':
        visit(node.operand)
        return
      case 'binary':
        visit(node.left)
        visit(node.right)
        return
      case 'call':
        for (const arg of node.args) visit(arg)
        return
      default:
        throw new Error(`unreachable node type: ${node.type}`)
    }
  }

  visit(ast)
  return [...found.values()].sort(compareAddresses).map((p) => p.key)
}
"}

