{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-sp1tQZ/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { parseInput } from './parse.js'
import { buildRegions, resolveRegion } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', chunk => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function renderMerge(items, includeBase) {
  const out = []
  let conflict = false
  for (const item of items) {
    if (item.type === 'stable') {
      out.push(...item.lines)
      continue
    }
    const resolution = resolveRegion(item)
    if (resolution.kind === 'mine' || resolution.kind === 'both') {
      out.push(...item.mine)
    } else if (resolution.kind === 'theirs') {
      out.push(...item.theirs)
    } else {
      conflict = true
      out.push('<<<<<<< mine')
      out.push(...item.mine)
      if (includeBase) {
        out.push('||||||| base')
        out.push(...item.base)
      }
      out.push('=======')
      out.push(...item.theirs)
      out.push('>>>>>>> theirs')
    }
  }
  return { lines: out, conflict }
}

function renderRegions(items) {
  const out = []
  let conflict = false
  for (const item of items) {
    if (item.type === 'stable') {
      out.push(`stable ${item.lines.length}`)
      continue
    }
    const resolution = resolveRegion(item)
    if (resolution.kind === 'mine') out.push(`mine ${item.mine.length}`)
    else if (resolution.kind === 'theirs') out.push(`theirs ${item.theirs.length}`)
    else if (resolution.kind === 'both') out.push(`both ${item.mine.length}`)
    else {
      conflict = true
      out.push(`conflict mine=${item.mine.length} base=${item.base.length} theirs=${item.theirs.length}`)
    }
  }
  return { lines: out, conflict }
}

async function main() {
  const [mode] = process.argv.slice(2)
  if (process.argv.length !== 3 || !MODES.has(mode)) {
    fail('error: usage: cli.js merge|merge2|regions')
    return
  }

  const input = await readStdin()
  const parts = parseInput(input)
  if (parts === null) {
    fail('error: expected three parts separated by %%%')
    return
  }

  const [mine, base, theirs] = parts
  const items = buildRegions(mine, base, theirs)

  const result =
    mode === 'regions' ? renderRegions(items) : renderMerge(items, mode === 'merge')

  const text = result.lines.map(line => `${line}\n`).join('')
  process.stdout.write(text)
  process.exit(result.conflict ? 1 : 0)
}

main()
"}

