{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-terZ5e/src/render.js","content":"import { computeSchedule } from './graph.js'
import { packSchedule } from './pack.js'

export function renderWaves(tasks, deps) {
  const { finish, depth } = computeSchedule(tasks, deps)
  const names = [...tasks.keys()].sort()

  const waves = []
  for (const name of names) {
    const d = depth.get(name)
    waves[d] = waves[d] ?? []
    waves[d].push(name)
  }

  const lines = []
  for (let k = 0; k < waves.length; k++) {
    lines.push(`wave ${k}: ${waves[k].join(' ')}`)
  }
  const total = finish.size === 0 ? 0 : Math.max(...finish.values())
  lines.push(`total ${total}`)
  return lines.map((line) => `${line}\n`).join('')
}

export function renderExplain(tasks, deps) {
  const { start, finish, depth } = computeSchedule(tasks, deps)
  const names = [...tasks.keys()].sort()

  const lines = names.map(
    (name) => `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`,
  )
  const total = finish.size === 0 ? 0 : Math.max(...finish.values())
  lines.push(`total ${total}`)
  return lines.map((line) => `${line}\n`).join('')
}

export function renderPack(tasks, deps, workerCount) {
  const { workers, makespan } = packSchedule(tasks, deps, workerCount)
  const lines = workers.map((worker, index) => {
    const runs = worker.runs.map((run) => ` ${run.name}@${run.start}-${run.finish}`).join('')
    return `worker ${index}:${runs}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.map((line) => `${line}\n`).join('')
}
"}

