const INTEGER_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*([eE][+-]?\d+(_\d+)*)?|[eE][+-]?\d+(_\d+)*)$/

/** Strips underscores and leading zeros, keeping the sign except for zero. */
function normalizeInteger(raw) {
  const digits = raw.replace(/_/g, '')
  let sign = ''
  let body = digits
  if (body[0] === '+') body = body.slice(1)
  else if (body[0] === '-') { sign = '-'; body = body.slice(1) }
  body = body.replace(/^0+(?=\d)/, '')
  if (body === '0') sign = ''
  return sign + body
}

/** Classifies an unquoted value token as a boolean, integer, or float. */
export function classifyBareword(text, lineNo) {
  if (text === 'true') return { kind: 'boolean', value: true }
  if (text === 'false') return { kind: 'boolean', value: false }
  if (INTEGER_RE.test(text)) return { kind: 'integer', text: normalizeInteger(text) }
  if (FLOAT_RE.test(text)) return { kind: 'float', value: Number(text.replace(/_/g, '')) }
  throw new ParseError(lineNo, `invalid value ${text}`)
}
