{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-uMkwQy/src/parser.js","content":"import { ParseError, NameParseFailure } from './errors.js'
import { tokenizeLine, TokenStream } from './lexer.js'
import { createTable, createArrayTable, joinPath, keySeg, walkIntermediate } from './tree.js'
import { classifyBareword } from './values.js'

const NAME_RE = /^[A-Za-z0-9_-]+$/

/** Consumes one name token (bareword or quoted string), or returns null. */
function tryConsumeName(ts) {
  const tok = ts.peek()
  if (!tok) return null
  if (tok.type === 'STRING') { ts.next(); return tok.value }
  if (tok.type === 'BAREWORD' && NAME_RE.test(tok.text)) { ts.next(); return tok.text }
  return null
}

/** Parses `name(.name)*`, throwing NameParseFailure when a name is missing. */
function parseDottedName(ts) {
  const first = tryConsumeName(ts)
  if (first === null) throw new NameParseFailure(true)
  const parts = [first]
  while (ts.peek() && ts.peek().type === 'DOT') {
    ts.next()
    const nm = tryConsumeName(ts)
    if (nm === null) throw new NameParseFailure(false)
    parts.push(nm)
  }
  return parts
}

/** Dotted-name parsing in header/inline-table contexts always wants `expected a name`. */
function parseDottedNameOrNameError(ts, lineNo) {
  try {
    return parseDottedName(ts)
  } catch (e) {
    if (e instanceof NameParseFailure) throw new ParseError(lineNo, 'expected a name')
    throw e
  }
}

function parseValue(ts, path, lineNo) {
  const tok = ts.peek()
  if (!tok) throw new ParseError(lineNo, 'expected a value')
  if (tok.type === 'STRING') { ts.next(); return { kind: 'string', value: tok.value } }
  if (tok.type === 'LBRACKET') return parseArray(ts, path, lineNo)
  if (tok.type === 'LBRACE') return parseInlineTable(ts, path, lineNo)
  if (tok.type === 'BAREWORD') { ts.next(); return classifyBareword(tok.text, lineNo) }
  throw new ParseError(lineNo, 'expected a value')
}

function parseArray(ts, path, lineNo) {
  ts.next() // consume '['
  const items = []
  if (ts.peek() && ts.peek().type === 'RBRACKET') { ts.next(); return { kind: 'array', items, path } }
  let idx = 0
  for (;;) {
    if (!ts.peek()) throw new ParseError(lineNo, 'unterminated array')
    const val = parseValue(ts, [...path, { type: 'index', i: idx }], lineNo)
    items.push(val)
    idx++
    const nxt = ts.peek()
    if (!nxt) throw new ParseError(lineNo, 'unterminated array')
    if (nxt.type === 'COMMA') {
      ts.next()
      const after = ts.peek()
      if (after && after.type === 'RBRACKET') { ts.next(); break }
      continue
    }
    if (nxt.type === 'RBRACKET') { ts.next(); break }
    throw new ParseError(lineNo, 'unterminated array')
  }
  return { kind: 'array', items, path }
}

function parseInlineTable(ts, path, lineNo) {
  ts.next() // consume '{'
  const table = createTable(path)
  if (ts.peek() && ts.peek().type === 'RBRACE') { ts.next(); return table }
  for (;;) {
    const parts = parseDottedNameOrNameError(ts, lineNo)
    const eq = ts.peek()
    if (!eq || eq.type !== 'EQUALS') throw new ParseError(lineNo, 'expected = in an inline table')
    ts.next()
    const intermediate = parts.slice(0, -1)
    const last = parts[parts.length - 1]
    const container = walkIntermediate(table, intermediate, lineNo)
    if (container.map.has(last)) {
      throw new ParseError(lineNo, `key ${joinPath(keySeg(container.path, last))} is defined twice`)
    }
