function compareCodePoints(a, b) {
  const ca = [...a]
  const cb = [...b]
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    const pa = ca[i].codePointAt(0)
    const pb = cb[i].codePointAt(0)
    if (pa !== pb) return pa - pb
  }
  return ca.length - cb.length
}

function sortedKeys(map) {
  return [...map.keys()].sort(compareCodePoints)
}

const pad = (n) => '  '.repeat(n)

function serialize(node, level) {
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node.map)
      if (keys.length === 0) return '{}'
      const parts = keys.map(
        (k) => `${pad(level + 1)}${JSON.stringify(k)}: ${serialize(node.map.get(k), level + 1)}`,
      )
      return `{\n${parts.join(',\n')}\n${pad(level)}}`
    }
    case 'array':
    case 'array-table': {
      const items = node.items
      if (items.length === 0) return '[]'
      const parts = items.map((it) => `${pad(level + 1)}${serialize(it, level + 1)}`)
      return `[\n${parts.join(',\n')}\n${pad(level)}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
      return node.text
    case 'float':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error(`unreachable node kind ${node.kind}`)
  }
}

/** Prints a parsed document as indented JSON with a trailing newline. */
export function printJSON(root) {
  return `${serialize(root, 0)}\n`
}

function typeName(node) {
  if (node.kind === 'array' || node.kind === 'array-table') return 'array'
  return node.kind
}

function collectKeys(node, path, out) {
  if (node.kind === 'table') {
    for (const k of sortedKeys(node.map)) {
      const child = node.map.get(k)
      const childPath = path === '' ? k : `${path}.${k}`
      out.push(`${childPath} ${typeName(child)}`)
      collectKeys(child, childPath, out)
    }
  } else if (node.kind === 'array' || node.kind === 'array-table') {
    node.items.forEach((item, i) => {
      const childPath = `${path}[${i}]`
      out.push(`${childPath} ${typeName(item)}`)
      collectKeys(item, childPath, out)
    })
  }
