// dot always separates dotted-name segments, and `#`/`;` always start a
// comment here (the "sticks to a value" exception below does not apply).
const NAME_STOPS = new Set([' ', '\t', '.', '=', ',', '[', ']', '{', '}', '"', "'", '#', ';'])

