// `#`/`;` with no whitespace before it is swallowed into the value's text
// (making it invalid) rather than starting a comment, so neither is a stop.
const VALUE_STOPS = new Set([' ', '\t', ',', ']', '}', '"', "'", '=', '[', '{'])

/**
 * A cursor over one line of input. Reading is context-sensitive: names and
 * values use different bareword grammars, so callers choose which to read
 * rather than the line being tokenized uniformly up front.
 */
export class Cursor {
  constructor(line, lineNo) {
    this.line = line
    this.lineNo = lineNo
    this.pos = 0
    this.n = line.length
  }

  skipSpaces() {
    while (this.pos < this.n && (this.line[this.pos] === ' ' || this.line[this.pos] === '\t')) this.pos++
  }

  /** True at end of line or at the start of a comment, after skipping spaces. */
  atEnd() {
    this.skipSpaces()
    if (this.pos >= this.n) return true
    const c = this.line[this.pos]
    return c === '#' || c === ';'
  }

  peek() {
    return this.atEnd() ? undefined : this.line[this.pos]
  }

  tryChar(ch) {
    if (this.peek() === ch) {
      this.pos++
      return true
    }
    return false
  }

  /** Reads one name: a quoted string, or a bareword restricted to the name charset. */
  readName() {
