function parseDottedName(cur) {
  const first = cur.readName()
  if (first === null) throw new NameParseFailure(true)
  const parts = [first]
  while (cur.tryChar('.')) {
    const nm = cur.readName()
    if (nm === null) throw new NameParseFailure(false)
    parts.push(nm)
  }
  return parts
