function parseDottedNameOrNameError(cur) {
  try {
    return parseDottedName(cur)
  } catch (e) {
    if (e instanceof NameParseFailure) throw new ParseError(cur.lineNo, 'expected a name')
    throw e
  }
}

function parseValue(cur, path) {
  if (cur.atEnd()) throw new ParseError(cur.lineNo, 'expected a value')
  const c = cur.peek()
  if (c === ',' || c === ']' || c === '}') throw new ParseError(cur.lineNo, 'expected a value')
  if (c === '"' || c === "'") return { kind: 'string', value: cur.readQuotedString() }
  if (c === '[') return parseArray(cur, path)
  if (c === '{') return parseInlineTable(cur, path)
  const text = cur.readValueBareword()
  if (text === '') throw new ParseError(cur.lineNo, 'expected a value')
  return classifyBareword(text, cur.lineNo)
}

function parseArray(cur, path) {
  cur.tryChar('[')
  const items = []
  if (cur.tryChar(']')) return { kind: 'array', items, path }
  let idx = 0
  for (;;) {
    if (cur.atEnd()) throw new ParseError(cur.lineNo, 'unterminated array')
    const val = parseValue(cur, [...path, { type: 'index', i: idx }])
    items.push(val)
    idx++
    if (cur.atEnd()) throw new ParseError(cur.lineNo, 'unterminated array')
    if (cur.tryChar(',')) {
      if (cur.tryChar(']')) break
      continue
    }
    if (cur.tryChar(']')) break
    throw new ParseError(cur.lineNo, 'unterminated array')
  }
  return { kind: 'array', items, path }
}

