  cur.tryChar('{')
  const table = createTable(path)
  if (cur.tryChar('}')) return table
  for (;;) {
    const parts = parseDottedNameOrNameError(cur)
    if (!cur.tryChar('=')) throw new ParseError(cur.lineNo, 'expected = in an inline table')
    const intermediate = parts.slice(0, -1)
    const last = parts[parts.length - 1]
    const container = walkIntermediate(table, intermediate, cur.lineNo)
    if (container.map.has(last)) {
      throw new ParseError(cur.lineNo, `key ${joinPath(keySeg(container.path, last))} is defined twice`)
    }
    const childPath = keySeg(container.path, last)
    const val = parseValue(cur, childPath)
