    if (cur.atEnd()) throw new ParseError(cur.lineNo, 'unterminated inline table')
    if (cur.tryChar(',')) continue
    if (cur.tryChar('}')) break
    throw new ParseError(cur.lineNo, 'unterminated inline table')
  }
