  const last = parts[parts.length - 1]
  const container = walkIntermediate(current, intermediate, cur.lineNo)
  if (container.map.has(last)) {
    throw new ParseError(cur.lineNo, `key ${joinPath(keySeg(container.path, last))} is defined twice`)
  }
  const childPath = keySeg(container.path, last)
  const value = parseValue(cur, childPath)
  container.map.set(last, value)
  if (!cur.atEnd()) throw new ParseError(cur.lineNo, 'trailing text after a value')
