 * Reference resolution by RFC 3986 section 5.2.2, strict form (a reference
 * that repeats the base's scheme is still treated as an absolute URI).
 */

/**
 * Merges `refPath` onto `base`'s path, per RFC 3986 section 5.2.3.
 */
function mergePaths(base, refPath) {
  if (base.authority !== null && base.path === '') {
    return `/${refPath}`
  }
  const lastSlash = base.path.lastIndexOf('/')
  if (lastSlash === -1) {
    return refPath
  }
  return base.path.slice(0, lastSlash + 1) + refPath
}

/**
 * Resolves `reference` against `base` (both parsed components with a raw,
 * unsplit `authority` string or `null`) and returns the resolved, not yet
 * normalized, components.
 */
export function resolveReference(base, reference) {
  if (reference.scheme !== null) {
    return {
      scheme: reference.scheme,
      authority: reference.authority,
      path: reference.path,
      query: reference.query,
      fragment: reference.fragment,
    }
  }

  if (reference.authority !== null) {
    return {
      scheme: base.scheme,
      authority: reference.authority,
      path: reference.path,
      query: reference.query,
      fragment: reference.fragment,
    }
  }

  if (reference.path === '') {
    return {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: reference.query !== null ? reference.query : base.query,
      fragment: reference.fragment,
    }
  }

  const path = reference.path.startsWith('/') ? reference.path : mergePaths(base, reference.path)
  return {
    scheme: base.scheme,
    authority: base.authority,
    path,
    query: reference.query,
    fragment: reference.fragment,
  }
}
"}

